import{_ as e,o as i,c as d,ak as a}from"./chunks/framework.DvrM7GBU.js";const m=JSON.parse('{"title":"社区贡献与维护指南","description":"","frontmatter":{},"headers":[],"relativePath":"维护与报告/社区贡献与维护指南.md","filePath":"维护与报告/社区贡献与维护指南.md","lastUpdated":1777977084000}'),o={name:"维护与报告/社区贡献与维护指南.md"};function c(r,l,s,t,h,n){return i(),d("div",null,[...l[0]||(l[0]=[a('<h1 id="社区贡献与维护指南" tabindex="-1">社区贡献与维护指南 <a class="header-anchor" href="#社区贡献与维护指南" aria-label="Permalink to “社区贡献与维护指南”">​</a></h1><ul><li>分类：维护 / 社区协作</li><li>子系统：贡献流程 / 内容审核 / 持续维护</li><li>关键词标签：贡献、PR、分支、审核、维护、停更预案</li><li>来源类型：仓库协作规范</li><li>证据等级：已确认</li><li>完整度状态：已整理</li><li>版本号：4.x 系列通用</li><li>来源文件：<code>docs/维护与报告/维护流程说明.md</code></li><li>最后更新：2026-05-05</li><li>适合查询：如何参与贡献、如何规范提交、如何保持站点长期稳定</li></ul><h2 id="目的" tabindex="-1">目的 <a class="header-anchor" href="#目的" aria-label="Permalink to “目的”">​</a></h2><p>本指南用于建立 <code>Azek431/cysj-data</code> 资料库与 <code>cysjdocs.dpdns.org</code> 文档站的社区贡献与维护标准，降低新贡献者门槛，提升协同质量。</p><h2 id="适用对象" tabindex="-1">适用对象 <a class="header-anchor" href="#适用对象" aria-label="Permalink to “适用对象”">​</a></h2><ul><li>贡献文档、专题、OCR 证据的社区作者</li><li>修复链接、补充导航、增强维护流程的维护者</li><li>设计站点结构、部署与运维方案的开发者</li></ul><h2 id="贡献流程" tabindex="-1">贡献流程 <a class="header-anchor" href="#贡献流程" aria-label="Permalink to “贡献流程”">​</a></h2><ol><li>先在仓库中创建 issue，说明你要补充的模块或修复的页面。</li><li>关联 issue 后，基于 <code>main</code> 创建分支，建议命名规则： <ul><li><code>fix/&lt;问题编号&gt;-&lt;描述&gt;</code></li><li><code>feature/&lt;模块&gt;-&lt;描述&gt;</code></li><li><code>docs/&lt;章节&gt;-&lt;说明&gt;</code></li></ul></li><li>提交 PR 前，请确保： <ul><li>相关文档存在清晰的元信息字段；</li><li>是否存在对应 <code>docs/</code> 栏目且链接可访问；</li><li>已在页面中补齐 <code>来源文件</code>、<code>证据等级</code>、<code>最后更新</code>；</li><li>对导航、侧边栏、相关索引页的链接进行复查；</li><li>如果修改了页面结构，已确认无死链。</li></ul></li><li>发起 PR 时，关联 issue，补充 <code>修复内容</code>、<code>测试方式</code>、<code>是否添加新页面</code>。</li></ol><h2 id="文档贡献规范" tabindex="-1">文档贡献规范 <a class="header-anchor" href="#文档贡献规范" aria-label="Permalink to “文档贡献规范”">​</a></h2><ul><li>所有页面须补充统一头部字段： <ul><li><code>分类</code>、<code>子系统</code>、<code>关键词标签</code>、<code>来源类型</code>、<code>证据等级</code>、<code>完整度状态</code>、<code>版本号</code>、<code>来源文件</code>、<code>最后更新</code></li></ul></li><li>尽量使用简明中文标题，避免过长。</li><li>结论类语句需明确证据来源：<code>[已确认]</code>、<code>[高可信推断]</code>、<code>[待验证]</code>。</li><li>避免发布绝对性结论，除非直接来自官方教程或更新说明。</li><li>对于 OCR / 图片编号引用，必须补齐对应 <code>docs/OCR资料/映射表/OCR 图片编号映射表.md</code> 回链。</li></ul><h2 id="页面审查标准" tabindex="-1">页面审查标准 <a class="header-anchor" href="#页面审查标准" aria-label="Permalink to “页面审查标准”">​</a></h2><p>请在 PR 评审时重点检查：</p><ul><li>页面内容是否存在死链或无效引用。</li><li>目录是否与 <code>docs/总索引与导航/创游世界知识库总导航.md</code> 一致。</li><li>新增页面是否补充了 <code>关联文档</code>、<code>适合查询</code> 等辅助字段。</li><li>是否遵循 <code>docs/元信息/知识条目统一元数据规范.md</code> 的模板。</li></ul><h2 id="开发者协作规则" tabindex="-1">开发者协作规则 <a class="header-anchor" href="#开发者协作规则" aria-label="Permalink to “开发者协作规则”">​</a></h2><ul><li>新增页面优先在已有模块中创建，不推荐随意新增顶级目录。</li><li>内容修订建议使用 <code>docs/维护与报告/维护检查清单.md</code> 的优先级判断。</li><li>重要改动（如导航重构、VitePress 配置变更、搜索优化）需先发 issue 讨论。</li></ul><h2 id="长期维护与交接机制" tabindex="-1">长期维护与交接机制 <a class="header-anchor" href="#长期维护与交接机制" aria-label="Permalink to “长期维护与交接机制”">​</a></h2><h3 id="每周检查项" tabindex="-1">每周检查项 <a class="header-anchor" href="#每周检查项" aria-label="Permalink to “每周检查项”">​</a></h3><ul><li>更新日志是否同步写入 <code>docs/维护与报告/更新日志入口导航.md</code>。</li><li>核心导航页、侧边栏、首页是否仍然可用。</li><li>OCR 证据入口是否持续补齐新的编号映射。</li><li>是否存在 <code>待验证问题</code>。</li></ul><h3 id="交接机制" tabindex="-1">交接机制 <a class="header-anchor" href="#交接机制" aria-label="Permalink to “交接机制”">​</a></h3><ul><li>若主维护者暂停更新，建议至少保留一名社区协作者作为备份联系人。</li><li>维护者交接时，应同步： <ul><li>当前 issue / PR 状态；</li><li>关键待补清单；</li><li>站点部署与自动构建配置；</li><li>站点备份与恢复方案。</li></ul></li></ul><h3 id="停更预案" tabindex="-1">停更预案 <a class="header-anchor" href="#停更预案" aria-label="Permalink to “停更预案”">​</a></h3><p>如果站点进入长期停更，应至少保留：</p><ul><li>最新的仓库代码与 <code>docs/</code> 内容。</li><li><code>docs/public/robots.txt</code>、<code>docs/public/sitemap.xml</code>。</li><li><code>README.md</code> 中说明当前停更状态与继续贡献入口。</li><li>公告页面或 <code>docs/关于.md</code> 中写明停止维护说明。</li></ul><h2 id="备份与恢复" tabindex="-1">备份与恢复 <a class="header-anchor" href="#备份与恢复" aria-label="Permalink to “备份与恢复”">​</a></h2><ul><li>仓库即是最基础的版本备份。</li><li>额外建议定期导出 <code>docs/</code> 目录的静态文件与 <code>docs/public</code> 的静态资产。</li><li>站点部署建议开启自动构建日志和历史记录，以便恢复到可用版本。</li></ul><h2 id="贡献模板示例" tabindex="-1">贡献模板示例 <a class="header-anchor" href="#贡献模板示例" aria-label="Permalink to “贡献模板示例”">​</a></h2><ul><li>PR 标题示例：<code>docs: 补充新手阅读路线中核心导航入口</code></li><li>Issue 标题示例：<code>docs: 修复 OCR 证据入口链接错误</code></li><li>分支示例：<code>docs/new-oct-ocr-template</code></li></ul>',27)])])}const b=e(o,[["render",c]]);export{m as __pageData,b as default};
